import axios from 'axios';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';
import { PaymentCalcInfoResponseDTO, PaymentCalcInfoRequestDTO } from './dtos/payment-clac-info';
import { VoucherItemDTO } from './dtos/voucher-item';
import { VoucherListRequestDTO, VoucherListResponseDTO } from './dtos/voucher-list';

const getIssuedVoucherListUrl = (aliasNm?: string | null) => {
  if (aliasNm === 'ALL') {
    return `${API_URLS.vcIssueList}?aliasNm=ALL`;
  }

  if (aliasNm) {
    return `${API_URLS.vcIssueList}?aliasNm=${encodeURIComponent(aliasNm)}`;
  }

  return API_URLS.vcIssueList;
};

export const voucherApi = {
  // 모든 바우처 목록 조회
  getAllVoucherList: ({ paging, search }: VoucherListRequestDTO) =>
    resultify(
      axios.post<VoucherItemDTO[]>(API_URLS.vcReadList, {
        paging,
        search,
      }),
    ),

  // 지급된 바우처 목록 조회
  getIssuedVoucherList: ({ paging, search, aliasNm }: VoucherListRequestDTO) =>
    resultify(
      axios.post<VoucherListResponseDTO>(getIssuedVoucherListUrl(aliasNm), {
        paging,
        search,
      }),
    ),

  // 내 바우처 목록 조회
  getMyVoucherList: ({ paging, search, aliasNm }: VoucherListRequestDTO) =>
    resultify(
      axios.post<VoucherListResponseDTO>(getIssuedVoucherListUrl(aliasNm), {
        paging,
        search,
      }),
    ),

  // 결제 혜택가 조회
  getPaymentCalcInfo: ({ tbPayMastr }: PaymentCalcInfoRequestDTO) =>
    resultify(
      axios.post<PaymentCalcInfoResponseDTO>(API_URLS.vcPayCalcInfo, {
        tbPayMastr,
      }),
    ),
} as const;
